-- Job abilities for the player jobs: id, display name, job, level, target mask, recast
-- (seconds), recast id, client animation id, animation time, cast time, action type,
-- range and add type.  The ids, job/level gates and animation numbers are functional game
-- data cross-checked against LandSandBoat's abilities.sql; the table and names are Fanxi's.
CREATE TABLE IF NOT EXISTS job_abilities (
    id              INTEGER PRIMARY KEY,
    name            TEXT    NOT NULL,
    job             INTEGER NOT NULL DEFAULT 0,
    level           INTEGER NOT NULL DEFAULT 0,
    valid_targets   INTEGER NOT NULL DEFAULT 0,
    recast          INTEGER NOT NULL DEFAULT 0,
    recast_id       INTEGER NOT NULL DEFAULT 0,
    animation       INTEGER NOT NULL DEFAULT 0,
    animation_time  INTEGER NOT NULL DEFAULT 0,
    cast_time       INTEGER NOT NULL DEFAULT 0,
    action_type     INTEGER NOT NULL DEFAULT 6,
    range           REAL    NOT NULL DEFAULT 0,
    add_type        INTEGER NOT NULL DEFAULT 0);
